values ('bbbb0001-0000-4000-8000-00000000000b', 'en', null, 'Linear Algebra', 'A first pass through the language of vectors, matrices, and the transformations they encode — from adding arrows to reading off eigenvalues. Structure adapted from MIT OpenCourseWare 18.06 Linear Algebra (CC BY-NC-SA 4.0).', null, 'foundations', 11, true, 'math', '{bbbb0001-0000-4000-8000-000000000003}')
